function Eyebrow({ children, dark }) {
  return (
    <div
      style={{
        fontFamily: fontMono,
        fontSize: "0.72rem",
        letterSpacing: "0.18em",
        textTransform: "uppercase",
        color: dark ? "#9FC4E8" : c.teal,
        display: "flex",
        alignItems: "center",
        gap: "0.6em",
        marginBottom: "1rem",
      }}
    >
      <span style={{ width: 22, height: 1, background: dark ? "#9FC4E8" : c.teal, display: "inline-block" }} />
      {children}
    </div>
  );
}

function CompassMark({ size = 34 }) {
  return (
    <img
      src={LOGO_SRC}
      alt="Logo Mare Nostrum"
      width={size}
      height={size}
      style={{ width: size, height: size, objectFit: "contain", display: "block" }}
    />
  );
}

function RouteDiagram() {
  return (
    <div
      style={{
        position: "relative",
        borderRadius: 20,
        background: `linear-gradient(160deg, ${c.ink} 0%, ${c.navy} 55%, ${c.teal} 100%)`,
        padding: "2.4rem 1.8rem",
        overflow: "hidden",
        minHeight: 420,
      }}
    >
      {/* slow-rotating compass rose, background texture */}
      <svg
        viewBox="0 0 200 200"
        style={{
          position: "absolute",
          top: -40,
          right: -40,
          width: 280,
          height: 280,
          opacity: 0.14,
          animation: "spin-slow 90s linear infinite",
        }}
      >
        <circle cx="100" cy="100" r="92" stroke="#BEE3F8" strokeWidth="1" fill="none" />
        <circle cx="100" cy="100" r="70" stroke="#BEE3F8" strokeWidth="1" fill="none" />
        {Array.from({ length: 16 }).map((_, i) => {
          const angle = (i * 360) / 16;
          const long = i % 4 === 0;
          return (
            <line
              key={i}
              x1="100"
              y1="8"
              x2="100"
              y2={long ? "22" : "16"}
              stroke="#BEE3F8"
              strokeWidth={long ? 1.6 : 1}
              transform={`rotate(${angle} 100 100)`}
            />
          );
        })}
      </svg>

      <div style={{ position: "relative", zIndex: 2 }}>
        <div
          style={{
            fontFamily: fontMono,
            fontSize: "0.68rem",
            letterSpacing: "0.14em",
            color: "#9FC4E8",
            textTransform: "uppercase",
            marginBottom: "1.6rem",
          }}
        >
          Active lane &nbsp;·&nbsp; 01.13°N 103.99°E → 01.26°N 103.85°E
        </div>

        <svg viewBox="0 0 340 220" width="100%" height="auto" style={{ display: "block" }}>
          <defs>
            <linearGradient id="lane" x1="0" y1="0" x2="1" y2="1">
              <stop offset="0%" stopColor="#4299E1" />
              <stop offset="100%" stopColor="#38A169" />
            </linearGradient>
          </defs>

          {/* static faint base path */}
          <path
            id="lanepath"
            d="M 30 60 C 110 40, 150 130, 240 110 S 300 150, 315 165"
            stroke="#2A4A6B"
            strokeWidth="2"
            fill="none"
          />
          {/* animated dashed lane */}
          <path
            d="M 30 60 C 110 40, 150 130, 240 110 S 300 150, 315 165"
            stroke="url(#lane)"
            strokeWidth="2.2"
            strokeDasharray="6 7"
            fill="none"
            style={{ animation: "dash-flow 3.2s linear infinite" }}
          />

          {/* origin: Batam industrial warehouse */}
          <rect x="20" y="52" width="16" height="16" rx="2" fill="#F7FAFC" />
          <rect x="24" y="56" width="3" height="8" fill={c.navy} />
          <rect x="29" y="56" width="3" height="8" fill={c.navy} />
          <text x="12" y="42" fontFamily={fontMono} fontSize="9" fill="#CBD9E8">
            BATAM · WAREHOUSE A
          </text>

          {/* destination: Singapore port */}
          <circle cx="315" cy="165" r="5.5" fill="#F7FAFC" />
          <circle cx="315" cy="165" r="9.5" stroke="#38A169" strokeWidth="1.4" fill="none">
            <animate attributeName="r" values="9.5;16;9.5" dur="2.6s" repeatCount="indefinite" />
            <animate attributeName="opacity" values="0.9;0;0.9" dur="2.6s" repeatCount="indefinite" />
          </circle>
          <text x="260" y="192" fontFamily={fontMono} fontSize="9" fill="#CBD9E8">
            SINGAPORE PORT
          </text>

          {/* moving marker along the lane = shipment position */}
          <circle r="4.2" fill="#F7FAFC">
            <animateMotion
              dur="3.2s"
              repeatCount="indefinite"
              path="M 30 60 C 110 40, 150 130, 240 110 S 300 150, 315 165"
            />
          </circle>
        </svg>

        <div
          style={{
            marginTop: "1.6rem",
            display: "grid",
            gridTemplateColumns: "1fr 1fr",
            gap: "0.75rem",
          }}
        >
          <div style={{ borderTop: "1px solid #2A4A6B", paddingTop: "0.6rem" }}>
            <div style={{ fontFamily: fontMono, fontSize: "0.66rem", color: "#8FB4D8", letterSpacing: "0.08em" }}>
              TRUCK STATUS
            </div>
            <div style={{ fontFamily: fontBody, fontSize: "0.86rem", color: "#F7FAFC", marginTop: 2 }}>
              En route to Batam port
            </div>
          </div>
          <div style={{ borderTop: "1px solid #2A4A6B", paddingTop: "0.6rem" }}>
            <div style={{ fontFamily: fontMono, fontSize: "0.66rem", color: "#8FB4D8", letterSpacing: "0.08em" }}>
              SHIP STATUS · SHIP ID
            </div>
            <div style={{ fontFamily: fontBody, fontSize: "0.86rem", color: "#F7FAFC", marginTop: 2 }}>
              At sea — ETA tracked
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function FeatureCard({ icon: Icon, title, desc, accent }) {
  return (
    <div
      style={{
        background: "#fff",
        border: `1px solid ${c.line}`,
        borderRadius: 14,
        padding: "1.5rem",
        transition: "transform 0.2s ease, box-shadow 0.2s ease",
      }}
      className="feature-card"
    >
      <div
        style={{
          width: 38,
          height: 38,
          borderRadius: 10,
          background: accent + "1A",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          marginBottom: "1rem",
        }}
      >
        <Icon size={18} color={accent} strokeWidth={2} />
      </div>
      <h3 style={{ fontFamily: fontBody, fontWeight: 600, fontSize: "1.02rem", color: c.ink, margin: "0 0 0.4rem" }}>
        {title}
      </h3>
      <p style={{ fontFamily: fontBody, fontSize: "0.9rem", color: "#4A5F73", lineHeight: 1.55, margin: 0 }}>
        {desc}
      </p>
    </div>
  );
}

function StepRow({ number, title, desc, last }) {
  return (
    <div
      style={{
        display: "flex",
        gap: "1.5rem",
        paddingBottom: last ? 0 : "2rem",
        marginBottom: last ? 0 : "2rem",
        borderBottom: last ? "none" : `1px solid ${c.line}`,
      }}
    >
      <div
        style={{
          fontFamily: fontMono,
          fontSize: "0.85rem",
          color: c.aqua,
          minWidth: 34,
          paddingTop: "0.2rem",
        }}
      >
        {number}
      </div>
      <div>
        <h3 style={{ fontFamily: fontDisplay, fontWeight: 600, fontSize: "1.2rem", color: c.ink, margin: "0 0 0.4rem" }}>
          {title}
        </h3>
        <p style={{ fontFamily: fontBody, fontSize: "0.94rem", color: "#4A5F73", lineHeight: 1.65, margin: 0, maxWidth: 520 }}>
          {desc}
        </p>
      </div>
    </div>
  );
}

